#[cfg(test)]
mod release_marker_tests {
    use super::BrokerReleaseMarker;

    #[test]
    fn release_marker_wire_round_trip_and_generation_path() {
        for forced in [false, true] {
            let marker = BrokerReleaseMarker {
                instance_id: "generation-123".into(),
                forced,
            };
            let wire = serde_json::to_value(&marker).unwrap();
            assert_eq!(
                wire,
                serde_json::json!({"instanceId": "generation-123", "forced": forced})
            );
            assert_eq!(
                serde_json::from_value::<BrokerReleaseMarker>(wire).unwrap(),
                marker
            );
        }
        for descriptor in ["data/device-broker.json", "data/device-broker"] {
            assert_eq!(
                BrokerReleaseMarker::path_for(std::path::Path::new(descriptor), "ab"),
                std::path::PathBuf::from("data/device-broker.released-6162.json")
            );
        }
        let descriptor = std::path::Path::new("data/device-broker.json");
        assert_ne!(
            BrokerReleaseMarker::path_for(descriptor, "ab"),
            BrokerReleaseMarker::path_for(descriptor, "ac")
        );
        let hostile = BrokerReleaseMarker::path_for(descriptor, "../other/☃");
        assert_eq!(
            hostile,
            std::path::PathBuf::from("data/device-broker.released-2e2e2f6f746865722fe29883.json")
        );
        assert_eq!(hostile.parent(), descriptor.parent());
        assert_eq!(
            BrokerReleaseMarker::path_for(descriptor, "..\\other"),
            std::path::PathBuf::from("data/device-broker.released-2e2e5c6f74686572.json")
        );
        for invalid in [
            serde_json::json!({"instanceId": "generation-123"}),
            serde_json::json!({"forced": true}),
            serde_json::json!({"instanceId": "generation-123", "forced": "true"}),
        ] {
            assert!(serde_json::from_value::<BrokerReleaseMarker>(invalid).is_err());
        }
    }
}

